/* Home lower screens only. Opening and other routes are preserved. */
(()=>{
const previousHome=home,previousBind=bindCineInteractions;
const stageNames=['未熟','转色期','着色期','完熟'];
const stages=['青绿底色占主导，先观察颜色分布。','青绿与黄橙交织，留意局部转色。','橙色逐渐铺开，表面纹理仍然清晰。','充分着色的外观，不代表糖度或脱涩状态。'];
home=function(){const original=previousHome();return original.slice(0,original.indexOf('<section class="ex-orchard'))+`
<section class="hf-orchard" id="collection" aria-labelledby="hf-orchard-title">
<div class="hf-orchard-world"><img class="hf-orchard-photo" src="assets/orchard-close-v2.webp" alt="艺术化果枝近景，三枚柿果与虚化远山"><div class="hf-orchard-shade"></div></div>
<div class="hf-orchard-copy"><span class="hf-eyebrow">01 — 走近枝头</span><h2 id="hf-orchard-title">把山野，<br>看得更近一点。</h2><p>从远山到果皮的细纹。<br>每一次观察，都从一个细节开始。</p><span class="hf-invitation"><i></i> 移动视线 · 点选果实</span></div>
<div class="hf-targets"><button class="hf-target" data-focus="0" style="--x:68%;--y:49%" aria-label="观察果皮颜色"><span class="hf-target-ring"></span><span class="hf-target-label">01 果皮颜色 <b>＋</b></span></button><button class="hf-target" data-focus="1" style="--x:84%;--y:30%" aria-label="观察果蒂与遮挡"><span class="hf-target-ring"></span><span class="hf-target-label">02 果蒂与遮挡 <b>＋</b></span></button></div>
<div class="hf-focus-note" hidden><span class="hf-eyebrow">枝头观察 / 艺术化场景</span><h3></h3><p></p><button type="button" class="hf-return">← 返回全景 <small>Esc</small></button></div>
<div class="hf-orchard-footer"><span>艺术化果园场景 · 非现场采集记录</span><a href="#roots">一方水土，果有来处 ↗</a></div>
</section>
<section class="hf-season" aria-labelledby="hf-season-title"><div class="hf-season-grain" aria-hidden="true"></div>
<div class="hf-season-copy"><span class="hf-eyebrow">02 — 看见秋色</span><h2 id="hf-season-title">一枚果实。<br><em>四种秋色。</em></h2><p>把时间交给指尖。<br>拖动色谱，观察外观颜色的变化。</p><div class="hf-current"><span id="hf-stage-number">03</span><div><h3 id="hf-stage-name">着色期</h3><p id="hf-stage-copy" aria-live="polite"></p></div></div><a class="hf-main-link" href="#recognize">观察自己的果实 <span>↗</span></a></div>
<div class="hf-specimen-area"><span class="hf-specimen-id">DIOSPYROS KAKI / 柿</span><div class="hf-specimen"><img class="hf-fruit" src="assets/persimmon-specimen-v2.webp" alt="柿果外观颜色模拟"><svg class="hf-calyx" viewBox="0 0 1312 1199" aria-hidden="true"><defs><filter id="hf-soft"><feGaussianBlur stdDeviation="4"/></filter><mask id="hf-calyx-mask"><path fill="white" filter="url(#hf-soft)" d="M315 314 Q390 285 485 270 L540 165 Q550 97 583 98 L641 115 Q701 119 759 107 L864 104 Q891 148 859 203 L823 232 Q916 266 982 303 L1000 322 Q970 365 842 379 Q817 460 753 503 Q701 531 652 515 Q589 494 565 441 Q458 454 379 405 Q326 373 290 326 Z"/></mask></defs><image href="assets/persimmon-specimen-v2.webp" width="1312" height="1199" mask="url(#hf-calyx-mask)"/></svg><span class="hf-inspection-lens" aria-hidden="true"></span></div><div class="hf-specimen-caption"><span>外观色彩模拟</span><span>移动光标，细看纹理</span></div></div>
<div class="hf-color-control"><div class="hf-control-label"><label for="hf-ripeness">拖动，留住这一刻的颜色</label><span id="hf-stage-label">着色期</span></div><input id="hf-ripeness" type="range" min="0" max="3" step=".01" value="2" aria-describedby="hf-color-disclaimer"><div class="hf-color-ticks">${stageNames.map((x,i)=>`<button type="button" data-stage="${i}" aria-pressed="${i===2}"><i></i>${x}</button>`).join('')}</div><small id="hf-color-disclaimer">同一果实的颜色模拟，非真实成熟过程或检测结论。</small></div>
</section>`};
bindCineInteractions=function(){if(route!=='home'){previousBind();return}const root=document.getElementById('app'),orchard=root.querySelector('.hf-orchard'),world=root.querySelector('.hf-orchard-world'),copy=root.querySelector('.hf-orchard-copy'),note=root.querySelector('.hf-focus-note'),targets=root.querySelector('.hf-targets');let active=-1,trigger=null;const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
let frame=0,px=0,py=0,tx=0,ty=0;const apply=()=>{px+=(tx-px)*.07;py+=(ty-py)*.07;orchard.style.setProperty('--px',px+'px');orchard.style.setProperty('--py',py+'px');if(Math.abs(tx-px)+Math.abs(ty-py)>.05)frame=requestAnimationFrame(apply);else frame=0};
if(!reduce&&matchMedia('(pointer:fine)').matches){orchard.onpointermove=e=>{if(active>=0)return;let r=orchard.getBoundingClientRect();tx=((e.clientX-r.left)/r.width-.5)*12;ty=((e.clientY-r.top)/r.height-.5)*8;if(!frame)frame=requestAnimationFrame(apply)};orchard.onpointerleave=()=>{tx=ty=0;if(!frame)frame=requestAnimationFrame(apply)}}
function close(){active=-1;orchard.classList.remove('hf-focused');note.hidden=true;copy.inert=false;targets.inert=false;world.style.removeProperty('--focus-x');world.style.removeProperty('--focus-y');trigger?.focus()}
root.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{trigger=b;active=+b.dataset.focus;orchard.classList.add('hf-focused');let mobile=matchMedia('(max-width:760px)').matches;world.style.setProperty('--focus-x',mobile?(active?'18%':'60%'):(active?'84%':'68%'));world.style.setProperty('--focus-y',mobile?(active?'64%':'54%'):(active?'30%':'49%'));note.hidden=false;copy.inert=true;targets.inert=true;note.querySelector('h3').textContent=active?'果蒂，也值得看清。':'颜色，不止一种。';note.querySelector('p').textContent=active?'果蒂与枝条容易遮住局部表面。拍摄时，尽量让目标完整入镜。':'留意明暗与着色分布。外观颜色是一条线索，不能替代内部品质检测。';note.querySelector('button').focus()});root.querySelector('.hf-return').onclick=close;orchard.onkeydown=e=>{if(e.key==='Escape'&&active>=0)close()};
const range=root.querySelector('#hf-ripeness'),fruit=root.querySelector('.hf-fruit'),lens=root.querySelector('.hf-inspection-lens'),specimen=root.querySelector('.hf-specimen');function update(){let v=+range.value,k=Math.round(v),hue=65-v*24;fruit.style.filter=`hue-rotate(${hue}deg) saturate(${.52+v*.14})`;lens.style.filter=fruit.style.filter;root.querySelector('#hf-stage-number').textContent='0'+(k+1);root.querySelector('#hf-stage-name').textContent=stageNames[k];root.querySelector('#hf-stage-label').textContent=stageNames[k];root.querySelector('#hf-stage-copy').textContent=stages[k];range.setAttribute('aria-valuetext',stageNames[k]);root.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.stage===k)));root.querySelector('.hf-season').style.setProperty('--warm',v/3)}range.oninput=update;range.onchange=()=>{range.value=Math.round(+range.value);update()};root.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{range.value=b.dataset.stage;update()});update();
if(!reduce&&matchMedia('(pointer:fine)').matches){specimen.onpointermove=e=>{let r=specimen.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;specimen.style.setProperty('--rx',(50-y)/20+'deg');specimen.style.setProperty('--ry',(x-50)/20+'deg');lens.style.left=x+'%';lens.style.top=y+'%';lens.style.backgroundPosition=x+'% '+y+'%';lens.classList.add('visible')};specimen.onpointerleave=()=>{specimen.style.setProperty('--rx','0deg');specimen.style.setProperty('--ry','0deg');lens.classList.remove('visible')}}
};
})();
